#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int dir_index(const char *s) {
    if (strcmp(s, "norte") == 0) return 0;
    if (strcmp(s, "leste") == 0) return 1;
    if (strcmp(s, "sul") == 0) return 2;
    return 3; /* oeste */
}

int main(void) {
    char a[10], b[10];

    if (scanf("%9s %9s", a, b) != 2) return 0;

    int x = dir_index(a);
    int y = dir_index(b);

    int d = abs(x - y);
    if (d > 2) d = 4 - d;

    printf("%d\n", d * 90);

    return 0;
}
```

